// 作成されたアプリIDを表示する。この番号を n8n の環境変数に設定してください。
const appId = $('① アプリの器を作成').first().json.app;
return [{ json: {
  '完了': '✅ AI経営日報アプリを作成しました',
  'KINTONE_AI_REPORT_APP_ID': String(appId),
  '次にやること': `n8nの環境変数に KINTONE_AI_REPORT_APP_ID=${appId} を設定してください`,
  'アプリを開く': `${($env.KINTONE_BASE_URL||'').replace(/\/$/,'')}/k/${appId}/`
} }];
